import 'package:flutter/material.dart';import 'package:sehatak/core/services/child_service.dart';class ChildHospitalsScreen extends StatelessWidget{const ChildHospitalsScreen({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('مستشفيات الأطفال')),body:StreamBuilder(stream:ChildService().streamHospitals(limit:20),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(16),children:s.data!.map((d)=>Card(child:ListTile(leading:Icon(d.emergency?Icons.emergency:Icons.local_hospital,color:d.emergency?Colors.red:const Color(0xFF00BCD4)),title:Text(d.name),subtitle:Text('${d.address}\n${d.phone}'),trailing:d.emergency?const Text('طوارئ',style:TextStyle(color:Colors.red)):null))).toList());}));}}
